/* 内置兜底照片（二课拍照/定位签到用；图库没有图时提交它）。
 * 由 tools 生成：原图 desktop/1ct/assets/fallback-sign.jpg → 800px / q72 → data URL。
 * 内联而不运行时 fetch：打包后渲染层是 file:// 源，fetch file:// 会被 CORS 拦。
 */
(function () {
  var DATA_URL = 'data:image/jpeg;base64,';
  window.ONE_CT_FALLBACK_PHOTO = DATA_URL;
  if (typeof module !== 'undefined' && module.exports) module.exports = DATA_URL;
})();
